from taf.cloud.lcmaas.schemas.schema_base import SchemaObject, SchemaField


class NeatInfoV1(SchemaObject):
    neat_name = SchemaField(name="name", not_null=True)
    mgmt_url = SchemaField(name="mgmt_url", not_null=True)
    auth_url = SchemaField(name="auth_url", not_null=True)
    username = SchemaField(name="username", not_null=True)
    password = SchemaField(name="password", not_null=True)
    client_id = SchemaField(name="client_id", not_null=True)
    ca_certs = SchemaField(name="ca_certs", optional=True)

    def __init__(self, neat_name, mgmt_url, auth_url, username, password, client_id, ca_certs):
        self.neat_name = neat_name
        self.mgmt_url = mgmt_url
        self.auth_url = auth_url
        self.username = username
        self.password = password
        self.client_id = client_id
        self.ca_certs = ca_certs

        super(NeatInfoV1, self).__init__()
